# Sourced by future adapters only. Never source on the host.
set -eu
umask 077
fail() { echo 'Disposable harness startup rejected' >&2; exit 78; }
[ "$(id -u)" = 10001 ] && [ "$(id -g)" = 10001 ] || fail
[ "$HOME" = /var/lib/grocery-harness/home ] || fail
[ "$TMPDIR" = /var/lib/grocery-harness/tmp ] || fail
# No runtime chown, mkdir fallback or writable-root exception.
for directory in /var/lib/grocery-harness "$HOME" "$TMPDIR"; do
    [ -d "$directory" ] && [ -w "$directory" ] || fail
done
# Future credentials must be generated by the protected executor, never supplied
# from ambient host configuration. This syntax check is NOT provenance proof.
hex64() {
    [ "${#1}" = 64 ] || fail
    case "$1" in *[!0-9a-f]*) fail ;; esac
}
